parts.openscad_module:
$fn = 128;

flange_od       = 165;
flange_t        = 20;
bolt_circle     = 125;
n_bolts         = 4;
bolt_hole_d     = 18.5;
raised_face_od  = 90;
raised_face_h   = 2;
bolt_offset_deg = 22.5;

module blind_flange_dn50() {
  difference() {
    union() {
      cylinder(h = flange_t, d = flange_od, center = true);
      translate([0, 0, flange_t/2 + raised_face_h/2])
        cylinder(h = raised_face_h, d = raised_face_od, center = true);
    }
    for (i = [0 : n_bolts - 1]) {
      angle = 360 * i / n_bolts + bolt_offset_deg;
      translate([cos(angle) * bolt_circle/2, sin(angle) * bolt_circle/2, 0])
        cylinder(h = flange_t + raised_face_h + 2, d = bolt_hole_d, center = true, $fn = 32);
    }
  }
}

blind_flange_dn50();
